#include <cstddef>
#include <string>
#include <vector>
#include <omp.h>

struct Book {
    std::string title;
    int pages;
};

size_t findLastShortBook(std::vector<Book> const& books) {
    size_t last_index = 0;
    int found = 0;

    #pragma omp parallel for reduction(max:last_index) reduction(||:found)
    for (size_t i = 0; i < books.size(); ++i) {
        if (books[i].pages < 100) {
            found = 1;
            if (i > last_index) {
                last_index = i;
            }
        }
    }

    return found ? last_index : static_cast<size_t>(-1);
}
